program.source:
SubProceso Swap(a Como Entero, b Como Entero)
  Definir saved Como Entero <- a;
  a <- b;
  b <- saved;
FinSubProceso

Algoritmo Main
  Definir primero, segundo Como Entero;
  Leer primero;
  Leer segundo;
  Swap(primero, segundo);
  Escribir primero, " ", segundo;
FinAlgoritmo

